            line = line.strip()
            if not line:
                continue
            try:
                entries.append(json.loads(line))
            except json.JSONDecodeError:
                continue
    return entries


def load_cases_by_id() -> dict[str, dict]:
    cases = {}
    if not CASES_DIR.exists():
