const fs = require('fs');
const path = require('path');

const ACTIONS_DIR = path.join(__dirname, '..', '..', 'data', 'actions');

function getUnresolvedActions() {
  if (!fs.existsSync(ACTIONS_DIR)) return [];
  const files = fs.readdirSync(ACTIONS_DIR).filter(f => f.startsWith('ACTION-') && f.endsWith('.json'));
  const unresolved = [];

  for (const file of files) {
    try {
      const data = JSON.parse(fs.readFileSync(path.join(ACTIONS_DIR, file), 'utf-8'));
      if (data.status === 'pending') {
        unresolved.push(data);
      }
    } catch { /* skip malformed */ }
  }
  return unresolved;
}

function formatAction(a) {
  const dueDate = new Date(a.due_by);
  const now = new Date();
  const daysLeft = Math.ceil((dueDate - now) / (1000 * 60 * 60 * 24));
  const overdue = daysLeft < 0 ? ' [OVERDUE]' : '';
  return `  • ${a.id}${overdue}\n    Action: ${a.action}\n    Due: ${a.due_by} (${daysLeft}d remaining)`;
}

function check() {
  const unresolved = getUnresolvedActions();
  if (unresolved.length === 0) return null;

  const now = new Date();
  const overdue = unresolved.filter(a => new Date(a.due_by) < now);
  const pending = unresolved.filter(a => new Date(a.due_by) >= now);

  let msg = `\n⛔ EXECUTION GATE: ${unresolved.length} unresolved action(s) block /stage0.\n`;
  msg += `\nAnalysis without execution feeds the deadlock loop.\n`;
  msg += `Resolve actions first, then run /stage0 again.\n\n`;

  if (overdue.length > 0) {
    msg += `🔴 OVERDUE (${overdue.length}):\n`;
    msg += overdue.map(formatAction).join('\n') + '\n\n';
  }
  if (pending.length > 0) {
    msg += `🟡 PENDING (${pending.length}):\n`;
    msg += pending.map(formatAction).join('\n') + '\n\n';
  }

  msg += `Commands:\n`;
  msg += `  /action resolve <id> completed "<what happened>"\n`;
  msg += `  /action resolve <id> abandoned "<why>"\n`;
  msg += `  /action list\n\n`;
  msg += `Override (not recommended): /stage0 --skip-gate\n`;

  return { block: overdue.length > 0, warn: pending.length > 0, message: msg };
}

module.exports = { check, getUnresolvedActions };

